//! Running a conformance lab for real: generated by this checkout's `isoloom` for a target, then
//! run with the commands the generated files' header documents, and nothing else (no runner):
//!
//! - `docker`: `docker compose up -d --build --wait`; the check services (the `check` profile's)
//!   run, and each `checks/isoloom-exec-<service>.sh` piped into its service; then `down -v`.
//! - `vagrant`: `vagrant up` on the provider; each machine up (a machine `vagrant up` leaves down,
//!   the access machine, brought up), and its checks run over `vagrant ssh`; then `destroy -f`.
//!
//! Each check prints an `isoloom-check: PASS <name>` or `FAIL <name>: <why>` line, read back by
//! the names the lab's checks have (a name may hold `: `, as a fact's does). The containers run
//! under a project name of the lab's own, so nothing else's are touched; the environment is taken
//! down unless kept.

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use isoloom_catalogue::conformance::{ConformanceLab, Form, Run};

use crate::{Res, process, repo};

/// What a check script prints before each result.
const MARK: &str = "isoloom-check: ";

/// What runs a lab: `isoloom`, the work folder, the VM form's provider (`docker` and `vagrant`
/// are found on the `PATH`).
pub(crate) struct Harness {
    pub isoloom: PathBuf,
    pub work: PathBuf,
    pub provider: String,
    pub keep: bool,
}

/// This checkout's `isoloom`, built.
pub(crate) fn isoloom(root: &Path) -> Res<PathBuf> {
    process::run(process::cargo(root).args(["build", "-q", "-p", "isoloom"]))?;
    let exe = if cfg!(windows) { "isoloom.exe" } else { "isoloom" };
    Ok(repo::target_dir(root).join("debug").join(exe))
}

/// `lab` written into `dir` (afresh): its spec and its project files.
pub(crate) fn write_lab(dir: &Path, lab: &ConformanceLab) -> Res<()> {
    if dir.exists() {
        repo::remove(dir)?;
    }
    std::fs::create_dir_all(dir)?;
    std::fs::write(dir.join("isoloom.yml"), &lab.spec)?;
    for (path, content) in &lab.project {
        let file = dir.join(path);
        if let Some(parent) = file.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(file, content)?;
    }
    Ok(())
}

/// The names `lab`'s checks print: its checks', then its facts' (`fact: <name>`).
pub(crate) fn check_names(lab: &ConformanceLab) -> Vec<String> {
    lab.checks.iter().cloned().chain(lab.facts.iter().map(|f| format!("fact: {f}"))).collect()
}

impl Harness {
    /// The lab in `dir` run in `form`: generated, up, checked, down; its checks read by `names`.
    pub(crate) fn run(&self, dir: &Path, form: Form, names: &[String]) -> Res<Run> {
        let lab = dir.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        let env = if form == Form::Vm {
            Env::Vagrant {
                dir: dir.join(".isoloom/vagrant"),
                provider: self.provider.clone(),
            }
        } else {
            Env::Compose {
                dir: dir.to_path_buf(),
                project: format!("isoloom-conformance-{lab}"),
            }
        };
        process::run(Command::new(&self.isoloom).args(["generate", "--target", env.target()]).arg(dir))?;
        let checked = match env.up() {
            Ok(()) => env.checks().map(|out| read_checks(&out, names)),
            Err(e) => Err(format!("{lab} didn't come up on {}: {e}", env.target()).into()),
        };
        if !self.keep
            && let Err(e) = env.down()
        {
            eprintln!(
                "catalogue check: taking {lab} down on {} failed: {e} (its files: {})",
                env.target(),
                dir.display()
            );
        }
        checked
    }
}

/// A lab's generated environment, run with the tool its files are for.
enum Env {
    /// The `docker` target's Compose project, under a project name of its own.
    Compose { dir: PathBuf, project: String },
    /// The `vagrant` target's Vagrantfile, on a provider.
    Vagrant { dir: PathBuf, provider: String },
}

impl Env {
    /// The target generated for it.
    fn target(&self) -> &'static str {
        match self {
            Env::Compose { .. } => "docker",
            Env::Vagrant { .. } => "vagrant",
        }
    }

    /// Its tool with `args`, in its folder.
    fn tool(&self, args: &[&str]) -> Command {
        let (program, dir, lead): (&str, &Path, Vec<&str>) = match self {
            Env::Compose { dir, project } => ("docker", dir, vec!["compose", "-f", ".isoloom/docker/compose.yml", "-p", project]),
            Env::Vagrant { dir, .. } => ("vagrant", dir, Vec::new()),
        };
        let mut cmd = process::tool(program);
        process::without_run_env(&mut cmd);
        cmd.current_dir(dir).args(lead).args(args);
        cmd
    }

    /// Brought up.
    fn up(&self) -> Res<()> {
        match self {
            Env::Compose { .. } => process::run(&mut self.tool(&["up", "-d", "--build", "--wait"])),
            Env::Vagrant { provider, .. } => process::run(&mut self.tool(&["up", "--provider", provider])),
        }
    }

    /// What its checks printed: the Compose check services (the `check` profile's) run and each
    /// `isoloom-exec-<service>.sh` piped into its service; each Vagrant machine's checks over
    /// `vagrant ssh`, a machine `vagrant up` left down (the access machine) brought up first.
    fn checks(&self) -> Res<String> {
        let mut out = String::new();
        match self {
            Env::Compose { dir, .. } => {
                let services = |args: &[&str]| -> Res<Vec<String>> { Ok(process::output(&mut self.tool(args))?.lines().map(str::to_owned).collect()) };
                let running = services(&["config", "--services"])?;
                for service in services(&["--profile", "check", "config", "--services"])? {
                    if !running.contains(&service) && service.starts_with("isoloom-check") {
                        out += &said(&mut self.tool(&["--profile", "check", "run", "--rm", &service]), None)?;
                    }
                }
                for service in &running {
                    let script = dir.join(format!(".isoloom/docker/checks/isoloom-exec-{service}.sh"));
                    if script.is_file() {
                        out += &said(&mut self.tool(&["exec", "-T", service, "sh", "-s"]), Some(&script))?;
                    }
                }
            }
            Env::Vagrant { provider, .. } => {
                for (machine, state) in machine_states(&process::output(&mut self.tool(&["status", "--machine-readable"]))?) {
                    if state != "running" {
                        process::run(&mut self.tool(&["up", &machine, "--provider", provider]))?;
                    }
                    out += &said(&mut self.tool(&["ssh", &machine, "-c", "sudo sh /var/lib/isoloom/checks.sh"]), None)?;
                }
            }
        }
        Ok(out)
    }

    /// Taken down, its volumes with it.
    fn down(&self) -> Res<()> {
        match self {
            Env::Compose { .. } => process::run(&mut self.tool(&["--profile", "check", "down", "-v"])),
            Env::Vagrant { .. } => process::run(&mut self.tool(&["destroy", "-f"])),
        }
    }
}

/// What `cmd` printed, `input` on its standard input; a check that failed exits non-zero, which
/// isn't an error here: its lines say which.
fn said(cmd: &mut Command, input: Option<&Path>) -> Res<String> {
    if let Some(file) = input {
        cmd.stdin(Stdio::from(std::fs::File::open(file)?));
    }
    let out = cmd.output().map_err(|e| format!("`{}` couldn't start: {e}", process::describe(cmd)))?;
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

/// Each machine of `vagrant status --machine-readable`'s output (`time,machine,state,<state>`),
/// with its state.
fn machine_states(status: &str) -> Vec<(String, String)> {
    status
        .lines()
        .filter_map(|l| match l.split(',').collect::<Vec<_>>().as_slice() {
            [_, machine, "state", state, ..] if !machine.is_empty() => Some(((*machine).to_owned(), (*state).to_owned())),
            _ => None,
        })
        .collect()
}

/// The checks the scripts' `output` reports, each read by the name in `names` it starts with (the
/// longest, as one name can begin another): its name, whether it passed, and why not.
pub(crate) fn read_checks(output: &str, names: &[String]) -> Run {
    let checks = output
        .lines()
        .filter_map(|l| l.trim_end_matches('\r').split_once(MARK).map(|(_, r)| r))
        .filter_map(|result| {
            let (ok, rest) = match result.split_once(' ')? {
                ("PASS", rest) => (true, rest),
                ("FAIL", rest) => (false, rest),
                _ => return None,
            };
            let name = names
                .iter()
                .filter(|n| rest == n.as_str() || rest.starts_with(&format!("{n}: ")))
                .max_by_key(|n| n.len())?;
            let why = rest.get(name.len() + 2..).unwrap_or_default();
            Some((name.clone(), ok, why.to_owned()))
        })
        .collect();
    Run { checks }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn each_result_is_read_by_the_name_it_starts_with_a_facts_colon_included() {
        let names = ["the port answers".to_owned(), "fact: the OS".to_owned(), "fact: the OS family".to_owned()];
        let output = concat!(
            "isoloom-check: PASS the port answers\n",
            "noise\n",
            "isoloom-check: FAIL fact: the OS: debian 12 \r\n",
            "isoloom-check: FAIL fact: the OS family: debian: linux\n",
            "isoloom-check: FAIL not one of the lab's: why\n",
        );
        assert_eq!(
            read_checks(output, &names).checks,
            [
                ("the port answers".to_owned(), true, String::new()),
                ("fact: the OS".to_owned(), false, "debian 12 ".to_owned()),
                ("fact: the OS family".to_owned(), false, "debian: linux".to_owned()),
            ]
        );
    }

    #[test]
    fn the_machines_and_their_states_are_read_from_vagrants_status() {
        let status = "1,web,metadata,provider,libvirt\n1,web,state,running\n1,probe,state,not_created\n1,,ui,info,x\n";
        assert_eq!(
            machine_states(status),
            [("web".to_owned(), "running".to_owned()), ("probe".to_owned(), "not_created".to_owned())]
        );
    }

    /// `isoloom`, `docker` and `vagrant` as stand-ins, each call logged: `docker compose` lists
    /// `web` and, under the `check` profile, `isoloom-check` too, whose run prints a PASS line;
    /// `vagrant` has `web` running and `probe` not created, each printing a PASS line over ssh.
    /// `up` fails when `fail-up` is there.
    #[cfg(unix)]
    fn harness(keep: bool) -> (isoloom_test_support::FakeBin, Harness) {
        let bin = isoloom_test_support::FakeBin::named("xtask-harness").unwrap();
        let (log, dir) = (bin.log(), bin.dir().display().to_string());
        bin.stand_in("isoloom", &format!("echo \"isoloom $*\" >> '{}'", log.display())).unwrap();
        let docker = format!(
            r#"echo "docker $*" >> '{log}'
case "$*" in
  *" up "*) [ ! -f '{dir}/fail-up' ] ;;
  *"--profile check config --services") printf 'web\nisoloom-check\n' ;;
  *"config --services") echo web ;;
  *"run --rm isoloom-check") echo 'isoloom-check: PASS the port answers' ;;
esac"#,
            log = log.display()
        );
        bin.stand_in("docker", &docker).unwrap();
        let vagrant = format!(
            r#"echo "vagrant $*" >> '{log}'
case "$1" in
  up) [ ! -f '{dir}/fail-up' ] ;;
  status) printf '1,web,state,running\n1,probe,state,not_created\n' ;;
  ssh) echo "isoloom-check: PASS from $2" ;;
esac"#,
            log = log.display()
        );
        bin.stand_in("vagrant", &vagrant).unwrap();
        let h = Harness {
            isoloom: bin.path().join("isoloom"),
            work: bin.dir().join("work"),
            provider: "libvirt".into(),
            keep,
        };
        (bin, h)
    }

    #[cfg(unix)]
    #[test]
    fn a_container_lab_runs_its_check_services_and_exec_scripts_then_comes_down() {
        let (bin, h) = harness(false);
        let dir = bin.dir().join("default");
        std::fs::create_dir_all(dir.join(".isoloom/docker/checks")).unwrap();
        std::fs::write(dir.join(".isoloom/docker/checks/isoloom-exec-web.sh"), "echo hi\n").unwrap();
        let run = process::testing::with_stand_ins(&bin.path(), || h.run(&dir, Form::Container, &["the port answers".to_owned()])).unwrap();
        assert_eq!(run.checks, [("the port answers".to_owned(), true, String::new())]);
        let c = "docker compose -f .isoloom/docker/compose.yml -p isoloom-conformance-default";
        assert_eq!(
            crate::testing::said(&bin),
            [
                format!("isoloom generate --target docker {}", dir.display()),
                format!("{c} up -d --build --wait"),
                format!("{c} config --services"),
                format!("{c} --profile check config --services"),
                format!("{c} --profile check run --rm isoloom-check"),
                format!("{c} exec -T web sh -s"),
                format!("{c} --profile check down -v"),
            ]
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_vm_lab_brings_up_what_vagrant_left_down_checks_each_machine_then_is_destroyed() {
        let (bin, h) = harness(false);
        let dir = bin.dir().join("default");
        std::fs::create_dir_all(dir.join(".isoloom/vagrant")).unwrap();
        let names = ["from web".to_owned(), "from probe".to_owned()];
        let run = process::testing::with_stand_ins(&bin.path(), || h.run(&dir, Form::Vm, &names)).unwrap();
        assert_eq!(
            run.checks,
            [("from web".to_owned(), true, String::new()), ("from probe".to_owned(), true, String::new())]
        );
        assert_eq!(
            crate::testing::said(&bin),
            [
                format!("isoloom generate --target vagrant {}", dir.display()),
                "vagrant up --provider libvirt".to_owned(),
                "vagrant status --machine-readable".to_owned(),
                "vagrant ssh web -c sudo sh /var/lib/isoloom/checks.sh".to_owned(),
                "vagrant up probe --provider libvirt".to_owned(),
                "vagrant ssh probe -c sudo sh /var/lib/isoloom/checks.sh".to_owned(),
                "vagrant destroy -f".to_owned(),
            ]
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_lab_that_failed_to_come_up_is_an_error_and_taken_down_unless_kept() {
        for keep in [false, true] {
            let (bin, h) = harness(keep);
            std::fs::write(bin.dir().join("fail-up"), "").unwrap();
            let dir = bin.dir().join("default");
            std::fs::create_dir_all(dir.join(".isoloom/vagrant")).unwrap();
            let e = process::testing::with_stand_ins(&bin.path(), || h.run(&dir, Form::Vm, &[]))
                .unwrap_err()
                .to_string();
            assert!(e.starts_with("default didn't come up on vagrant: "), "{e}");
            let ops: Vec<String> = bin.calls().unwrap().iter().filter(|c| c[0] == "vagrant").map(|c| c[1].clone()).collect();
            assert_eq!(ops, if keep { vec!["up"] } else { vec!["up", "destroy"] }, "keep: {keep}");
        }
    }
}
